g.script:
(function(){
  var TOP=111, VH=699, PH=2834, MAX=PH-VH, y=0, user=false, raf=0;
  var svg=document.documentElement, page=document.getElementById("page"), thumb=document.getElementById("thumb"),
      vp=document.getElementById("viewport"), hint=document.getElementById("hint");
  function set(v){ y=Math.max(0,Math.min(MAX,v)); page.setAttribute("y",TOP-y);
    thumb.setAttribute("y",TOP+4+(VH-8-302)*(y/MAX)); }
  function scale(){ var m=svg.getScreenCTM(); return m?m.a:1; }
  function takeover(){ if(!user){ user=true; cancelAnimationFrame(raf); hint.setAttribute("opacity","0"); } }
  // mouse wheel / trackpad: scroll the page inside the browser; at the top or bottom let the real page scroll on
  svg.addEventListener("wheel",function(e){
    var d=e.deltaY*(e.deltaMode===1?32:e.deltaMode===2?VH:1)/scale();
    if((d<0&&y<=0)||(d>0&&y>=MAX)) return;
    e.preventDefault(); takeover(); set(y+d);
  },{passive:false});
  // drag with mouse, finger or pen
  var drag=null;
  vp.addEventListener("pointerdown",function(e){ takeover(); drag={sy:e.clientY,y0:y,onThumb:e.target===thumb}; vp.style.cursor="grabbing"; try{vp.setPointerCapture(e.pointerId);}catch(_){} });
  vp.addEventListener("pointermove",function(e){ if(!drag) return; var d=(e.clientY-drag.sy)/scale();
    set(drag.onThumb? drag.y0+d*MAX/(VH-8-302) : drag.y0-d); });
  function end(){ drag=null; vp.style.cursor="grab"; }
  vp.addEventListener("pointerup",end); vp.addEventListener("pointercancel",end);
  vp.style.touchAction="none";
  // keyboard
  svg.addEventListener("keydown",function(e){ var k={ArrowDown:60,ArrowUp:-60,PageDown:VH*.9,PageUp:-VH*.9," ":VH*.9,Home:-1e5,End:1e5}[e.key];
    if(k){ e.preventDefault(); takeover(); set(y+k); } });
  // demo: once it's on screen, glide down the page and back up, until the visitor takes over
  function ease(t){ return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2; }
  function tween(a,b,ms,next){ var t0=performance.now(); (function step(now){ if(user) return;
      var t=Math.min(1,(now-t0)/ms); set(a+(b-a)*ease(t)); if(t<1) raf=requestAnimationFrame(step); else if(next) setTimeout(next,1200); })(t0); }
  var started=false;
  function demo(){ if(started||user) return; started=true; hint.setAttribute("opacity","1");
    setTimeout(function(){ var dn=Math.max(2500,MAX*4.5); tween(0,MAX,dn,function(){ tween(MAX,0,dn*.55,function(){ hint.setAttribute("opacity","0"); }); }); },900); }
  try{ new IntersectionObserver(function(es){ if(es[0].isIntersecting&&es[0].intersectionRatio>.5) demo(); },{threshold:[.5]}).observe(svg); }
  catch(_){ setTimeout(demo,600); }
  set(0);
})();
